00053     public function reload($id = null, $type = null) {
00054         global $bearsamppRoot, $bearsamppConfig, $bearsamppLang;
00055         Log::reloadClass($this);
00056 
00057         $this->name = $bearsamppLang->getValue(Lang::XLIGHT);
00058         $this->version = $bearsamppConfig->getRaw(self::ROOT_CFG_VERSION);
00059         parent::reload($id, $type);
00060 
00061         $this->enable = $this->enable && $bearsamppConfig->getRaw(self::ROOT_CFG_ENABLE);
00062         $this->service = new Win32Service(self::SERVICE_NAME);
00063         $this->log = Path::getLogsPath() . '/xlight.log';
00064 
00065         if ($this->bearsamppConfRaw !== false) {
00066             $this->exe = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_EXE];
00067             $this->SslPort = intval($this->bearsamppConfRaw[self::LOCAL_CFG_SSL_PORT]);
00068             $this->port = intval($this->bearsamppConfRaw[self::LOCAL_CFG_PORT]);
00069         }
00070 
00071         if (!$this->enable) {
00072             Log::info($this->name . ' is not enabled!');
00073             return;
00074         }
00075         if (!is_dir($this->currentPath)) {
00076             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->currentPath));
00077             return;
00078         }
00079         if (!is_dir($this->symlinkPath)) {
00080             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->symlinkPath));
00081             return;
00082         }
00083         if (!is_file($this->bearsamppConf)) {
00084             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_CONF_NOT_FOUND), $this->name . ' ' . $this->version, $this->bearsamppConf));
00085             return;
00086         }
00087         if (!is_file($this->exe)) {
00088             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_EXE_NOT_FOUND), $this->name . ' ' . $this->version, $this->exe));
00089             return;
00090         }
00091         if (empty($this->SslPort)) {
00092             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_INVALID_PARAMETER), self::LOCAL_CFG_SSL_PORT, $this->SslPort));
00093             return;
00094         }
00095         if (empty($this->port)) {
00096             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_INVALID_PARAMETER), self::LOCAL_CFG_PORT, $this->port));
00097             return;
00098         }
00099 
00100         $nssm = new Nssm(self::SERVICE_NAME);
00101         $nssm->setDisplayName(APP_TITLE . ' ' . $this->getName());
00102         $nssm->setBinPath($this->exe);
00103         $nssm->setParams(sprintf(self::SERVICE_PARAMS, $this->SslPort, $this->port));
00104         $nssm->setStart(Nssm::SERVICE_DEMAND_START);
00105         $nssm->setStdout(Path::getLogsPath() . '/xlight.log');
00106         $nssm->setStderr(Path::getLogsPath() . '/xlight.error.log');
00107 
00108         $this->service->setNssm($nssm);
00109     }
