00116     protected function replaceAll($params) {
00117         $content = file_get_contents($this->bearsamppConf);
00118 
00119         foreach ($params as $key => $value) {
00120             $content = preg_replace('|' . $key . ' = .*|', $key . ' = ' . '"' . $value.'"', $content);
00121             $this->bearsamppConfRaw[$key] = $value;
00122             switch ($key) {
00123                 case self::LOCAL_CFG_SSL_PORT:
00124                     $this->SslPort = intval($value);
00125                     break;
00126                 case self::LOCAL_CFG_PORT:
00127                     $this->port = intval($value);
00128                     break;
00129             }
00130         }
00131 
00132         file_put_contents($this->bearsamppConf, $content);
00133     }
