00143         $exists = $bearsamppRegistry->exists(
00144             Registry::HKEY_LOCAL_MACHINE,
00145             'SYSTEM\CurrentControlSet\Services\\' . self::SERVICE_NAME . '\Parameters',
00146             Nssm::INFO_APP_PARAMETERS
00147         );
00148         if ($exists) {
00149             return $bearsamppRegistry->setExpandStringValue(
00150                 Registry::HKEY_LOCAL_MACHINE,
00151                 'SYSTEM\CurrentControlSet\Services\\' . self::SERVICE_NAME . '\Parameters',
00152                 Nssm::INFO_APP_PARAMETERS,
00153                 sprintf(self::SERVICE_PARAMS, $this->SslPort, $this->port)
