00168     public function changePort($port, $checkUsed = false, $wbProgressBar = null) {
00169         global $bearsamppWinbinder;
00170 
00171         if (!Util::isValidPort($port)) {
00172             Log::error($this->getName() . ' port not valid: ' . $port);
00173             return false;
00174         }
00175 
00176         $port = intval($port);
00177         $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00178 
00179         $isPortInUse = Util::isPortInUse($port);
00180         if (!$checkUsed || $isPortInUse === false) {
00181             // bearsampp.conf
00182             $this->setPort($port);
00183             $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00184 
00185             // conf
00186             $this->update();
00187             $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00188 
00189             return true;
00190         }
00191 
00192         Log::debug($this->getName() . ' port in used: ' . $port . ' - ' . $isPortInUse);
00193         return $isPortInUse;
00194     }
