00203     public function checkPort($port, $showWindow = false) {
00204         global $bearsamppLang, $bearsamppWinbinder;
00205         $boxTitle = sprintf($bearsamppLang->getValue(Lang::CHECK_PORT_TITLE), $this->getName(), $port);
00206 
00207         if (!Util::isValidPort($port)) {
00208             Log::error($this->getName() . ' port not valid: ' . $port);
00209             return false;
00210         }
00211 
00212         $headers = HttpClient::getHeaders('127.0.0.1', $port);
00213         if (!empty($headers)) {
00214             if (UtilString::contains($headers[0], 'Xlight')) {
00215                 Log::debug($this->getName() . ' port ' . $port . ' is used by: ' . str_replace('220 ', '', $headers[0]));
00216                 if ($showWindow) {
00217                     $bearsamppWinbinder->messageBoxInfo(
00218                         sprintf($bearsamppLang->getValue(Lang::PORT_USED_BY), $port, str_replace('220 ', '', $headers[0])),
00219                         $boxTitle
00220                     );
00221                 }
00222                 return true;
00223             }
00224             Log::debug($this->getName() . ' port ' . $port . ' is used by another application');
00225             if ($showWindow) {
00226                 $bearsamppWinbinder->messageBoxWarning(
00227                     sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED_BY), $port),
00228                     $boxTitle
00229                 );
00230             }
00231         } else {
00232             Log::debug($this->getName() . ' port ' . $port . ' is not used');
00233             if ($showWindow) {
00234                 $bearsamppWinbinder->messageBoxError(
00235                     sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED), $port),
00236                     $boxTitle
00237                 );
00238             }
00239         }
00240 
00241         return false;
00242     }
