00264     protected function updateConfig($version = null, $sub = 0, $showWindow = false) {
00265         global $bearsamppLang, $bearsamppWinbinder;
00266 
00267         if (!$this->enable) {
00268             return true;
00269         }
00270 
00271         $version = $version == null ? $this->version : $version;
00272         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'Update ' . $this->name . ' ' . $version . ' config');
00273 
00274         $boxTitle = sprintf($bearsamppLang->getValue(Lang::SWITCH_VERSION_TITLE), $this->getName(), $version);
00275 
00276         $bearsamppConf = str_replace('xlight' . $this->getVersion(), 'xlight' . $version, $this->bearsamppConf);
00277         if (!file_exists($bearsamppConf)) {
00278             Log::error('bearsampp config files not found for ' . $this->getName() . ' ' . $version);
00279             if ($showWindow) {
00280                 $bearsamppWinbinder->messageBoxError(
00281                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR), $this->getName() . ' ' . $version),
00282                     $boxTitle
00283                 );
00284             }
00285             return false;
00286         }
00287 
00288         $bearsamppConfRaw = parse_ini_file($bearsamppConf);
00289         if ($bearsamppConfRaw === false || !isset($bearsamppConfRaw[self::ROOT_CFG_VERSION]) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version) {
00290             Log::error('bearsampp config file malformed for ' . $this->getName() . ' ' . $version);
00291             if ($showWindow) {
00292                 $bearsamppWinbinder->messageBoxError(
00293                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_MALFORMED_ERROR), $this->getName() . ' ' . $version),
00294                     $boxTitle
00295                 );
00296             }
00297             return false;
00298         }
00299 
00300         // bearsampp.conf
00301         $this->setVersion($version);
00302 
00303         return true;
00304     }
