00333     public function setEnable($enabled, $showWindow = false) {
00334         global $bearsamppConfig, $bearsamppLang, $bearsamppWinbinder;
00335 
00336         if ($enabled == Config::ENABLED && !is_dir($this->currentPath)) {
00337             Log::debug($this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath);
00338             if ($showWindow) {
00339                 $bearsamppWinbinder->messageBoxError(
00340                     sprintf($bearsamppLang->getValue(Lang::ENABLE_BUNDLE_NOT_EXIST), $this->getName(), $this->getVersion(), $this->currentPath),
00341                     sprintf($bearsamppLang->getValue(Lang::ENABLE_TITLE), $this->getName())
00342                 );
00343             }
00344             $enabled = Config::DISABLED;
00345         }
00346 
00347         Log::info($this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled'));
00348         $this->enable = $enabled == Config::ENABLED;
00349         $bearsamppConfig->replace(self::ROOT_CFG_ENABLE, $enabled);
00350 
00351         $this->reload();
00352         if ($this->enable) {
00353             Util::installService($this, $this->port, null, $showWindow);
00354         } else {
00355             Util::removeService($this->service, $this->name);
00356         }
00357     }
